#!/usr/bin/env python3
"""
agent-068_prereg4_score.py  (2026-08-06T18:05Z)

Executes commons/findings/agent-068_PREREG4_additive_7_vs_interacting_5_20260806T175200Z.md
on the untouched holdout of primes 100000 < p <= 150000 (4256 rows), and re-reports the
two spent holdouts side by side so the ordering claim (Q4) is checkable.

The 13-model list is the frozen list from agents/agent-068/additivity.py, unchanged:
  trend / mod24 / mod5 / mod24+mod5 additive / mod120 full / mod8 / mod3 /
  mod8+mod3 additive / mod24 full / mod120+mod16 additive / mod240 full /
  mod240+mod7 additive / mod840 full

WORDING SLIP IN THE PREREG, flagged rather than silently fixed: Q5 says
"mod24 + mod3 + mod8 additive", but the frozen model list contains "mod8 + mod3
ADDITIVE" (which is the model whose 0.0351/0.0358 shortfall Q5 quotes).  The frozen
model is what is scored; the prereg sentence was sloppy, the number it cites is not.

TRAIN = all primes 3 < p <= 20000.  Scoring rule identical to PREREG3.
stdlib + numpy for the solver, with a stdlib cross-check on the small models.
--selftest verifies the additive-vs-interaction machinery on planted data.
"""
import argparse, importlib.util, json, math, os, sys

import numpy as np

_D = os.path.dirname(os.path.abspath(__file__))
_S = importlib.util.spec_from_file_location(
    "fz", os.path.join(_D, "agent-068_erdos_prereg3_score_20260806T163500Z.py"))
FZ = importlib.util.module_from_spec(_S)
_S.loader.exec_module(FZ)

HOLDOUTS = [("20k-50k", "commons/data/agent-068_erdos_holdout_20k_50k_20260806T163000Z.json"),
            ("50k-100k", "commons/data/agent-068_erdos_holdout_50k_100k_20260806T164800Z.json"),
            ("100k-150k", "commons/data/agent-068_erdos_holdout_100k_150k_20260806T175000Z.json")]

MODELS = [("trend", [], None), ("mod24", [24], None), ("mod5", [5], None),
          ("mod24 + mod5 ADDITIVE", [24, 5], None),
          ("mod120 = mod24 x mod5 FULL", [], 120),
          ("mod8", [8], None), ("mod3", [3], None),
          ("mod8 + mod3 ADDITIVE", [8, 3], None),
          ("mod24 = mod8 x mod3 FULL", [], 24),
          ("mod120 + mod2bit ADDITIVE", [120, 16], None),
          ("mod240 FULL", [], 240),
          ("mod240 + mod7 ADDITIVE", [240, 7], None),
          ("mod840 FULL", [], 840)]


def keepset(tr, m):
    cnt = {}
    for r in tr:
        cnt[r["n"] % m] = cnt.get(r["n"] % m, 0) + 1
    return sorted(c for c, k in cnt.items() if k >= FZ.FLOOR)


def dummies(rows, m, keep):
    ref = keep[0]
    out = []
    tail = keep[1:]
    for r in rows:
        c = r["n"] % m
        d = [0.0] * (len(tail) + 1)
        if c in tail:
            d[tail.index(c)] = 1.0
        elif c != ref:
            d[-1] = 1.0
        out.append(d)
    return out


def design(tr, rows, specs, full):
    if full:
        return np.array(FZ.partition_design(rows, full, FZ.class_scheme(tr, full)), dtype=float)
    blocks = [dummies(rows, m, keepset(tr, m)) for m in specs]
    X = []
    for i, r in enumerate(rows):
        row = FZ.trend_row(r["n"])
        for b in blocks:
            row = row + b[i]
        X.append(row)
    return np.array(X, dtype=float)


def r2(y, p):
    return float(1 - ((y - p) ** 2).sum() / ((y - y.mean()) ** 2).sum())


def load_holdout(path):
    return [{"n": r["n"], "reps": r["representations"]}
            for r in json.load(open(path))["rows"]]


def selftest():
    ok = True
    # planted purely ADDITIVE mod-24 + mod-5 structure: additive model must match full mod120
    def mk(lo, hi, mode):
        rows = []
        for n in range(lo, hi):
            if n % 2 == 0 or n % 3 == 0 or n % 5 == 0:
                continue
            v = 0.4 * math.log(n)
            if mode == "additive":
                v += 0.3 * (n % 24 == 23) + 0.2 * (n % 5 == 4)
            else:  # pure interaction: only the joint cell fires
                v += 0.5 * ((n % 24 == 23) and (n % 5 == 4))
            rows.append({"n": n, "reps": math.exp(v)})
        return rows
    for mode, expect in (("additive", "additive~full"), ("interaction", "full>additive")):
        tr, ho = mk(1000, 20000, mode), mk(20000, 50000, mode)
        yt = np.array([math.log(r["reps"]) for r in tr])
        yh = np.array([math.log(r["reps"]) for r in ho])
        res = {}
        for name, specs, full in [("add", [24, 5], None), ("full", [], 120)]:
            Xt, Xh = design(tr, tr, specs, full), design(tr, ho, specs, full)
            b, *_ = np.linalg.lstsq(Xt, yt, rcond=None)
            res[name] = r2(yh, Xh @ b)
        print(f"  planted {mode:11s}: additive={res['add']:.6f} full={res['full']:.6f}")
        if mode == "additive":
            ok &= abs(res["add"] - res["full"]) < 1e-6 and res["add"] > 0.99
        else:
            ok &= res["full"] - res["add"] > 0.2
    print("SELFTEST", "PASS" if ok else "FAIL")
    return ok


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--out", default=None)
    a = ap.parse_args()
    if a.selftest:
        sys.exit(0 if selftest() else 1)

    tr, _ = FZ.load()
    yt = np.array([math.log(r["reps"]) for r in tr])
    print(f"TRAIN {len(tr)} primes {tr[0]['n']}..{tr[-1]['n']}")
    out = {"train_n": len(tr), "holdouts": {}, "models": [m[0] for m in MODELS]}
    tables = {}
    for label, path in HOLDOUTS:
        if not os.path.exists(path):
            print(f"  {label}: MISSING {path}")
            continue
        ho = load_holdout(path)
        yh = np.array([math.log(r["reps"]) for r in ho])
        tab = {}
        print(f"\n===== HOLDOUT {label} ({len(ho)} primes {ho[0]['n']}..{ho[-1]['n']}) =====")
        for name, specs, full in MODELS:
            Xt, Xh = design(tr, tr, specs, full), design(tr, ho, specs, full)
            b, *_ = np.linalg.lstsq(Xt, yt, rcond=None)
            v = r2(yh, Xh @ b)
            tab[name] = {"params": Xt.shape[1], "r2_oos": v}
            print(f"  {name:32s} p={Xt.shape[1]:4d}  r2_oos={v:.6f}")
        tables[label] = tab
        out["holdouts"][label] = {"n": len(ho), "table": tab}

    T = tables.get("100k-150k")
    if T:
        g = lambda k: T[k]["r2_oos"]
        best = max(T, key=lambda k: T[k]["r2_oos"])
        q = {}
        q["Q1_additive7_is_best"] = (best == "mod240 + mod7 ADDITIVE")
        q["Q1_best_model"] = best
        q["Q1_detail"] = {"add7": g("mod240 + mod7 ADDITIVE"), "mod240": g("mod240 FULL"),
                          "mod120": g("mod120 = mod24 x mod5 FULL")}
        five = g("mod120 = mod24 x mod5 FULL") - g("mod24 + mod5 ADDITIVE")
        seven = g("mod840 FULL") - g("mod240 + mod7 ADDITIVE")
        q["Q2_five_interacts_seven_does_not"] = (five > 0.04 and seven < 0)
        q["Q2_detail"] = {"five_interaction_gain": five, "seven_interaction_gain": seven}
        prev = tables.get("50k-100k")
        if prev:
            drops = {k: T[k]["r2_oos"] - prev[k]["r2_oos"] for k in T}
            q["Q3_all_13_lower_than_50k_100k"] = all(v < 0 for v in drops.values())
            q["Q3_detail"] = drops
            # Kendall tau = 1 test across all three holdouts
            def rank(tab):
                return [k for k in sorted(tab, key=lambda x: -tab[x]["r2_oos"])]
            r1, r2_, r3 = rank(tables["20k-50k"]), rank(prev), rank(T)
            q["Q4_identical_ordering"] = (r1 == r2_ == r3)
            q["Q4_orders"] = {"20k-50k": r1, "50k-100k": r2_, "100k-150k": r3}
        q["Q5_2adic_3adic_interaction_real"] = \
            (g("mod24 = mod8 x mod3 FULL") - g("mod8 + mod3 ADDITIVE")) > 0.02
        q["Q5_detail"] = g("mod24 = mod8 x mod3 FULL") - g("mod8 + mod3 ADDITIVE")
        out["verdicts"] = q
        print("\nVERDICTS")
        for k, v in q.items():
            if not k.endswith("detail") and k != "Q4_orders":
                print(f"  {k}: {v}")
        print(f"  Q1 detail: {q['Q1_detail']}")
        print(f"  Q2 detail: {q['Q2_detail']}")
        print(f"  Q5 detail: {q['Q5_detail']:.6f}")
        if "Q3_detail" in q:
            print("  Q3 drops 50k-100k -> 100k-150k:")
            for k, v in q["Q3_detail"].items():
                print(f"     {k:32s} {v:+.6f}")
    if a.out:
        json.dump(out, open(a.out, "w"), indent=1)
        print("wrote", a.out)


if __name__ == "__main__":
    main()

