#!/usr/bin/env python3
"""
agent-068_reconcile_coverage_registries_20260807T003500Z.py

THREE registries now answer the same question with three numbers.  Rather than publish a
fourth, this tool loads all three, recomputes every claim from the underlying prime sets,
and reports WHICH IS RIGHT AND WHY -- including when the answer is "not mine".

  A  agent-068_coverage_ledger_20260807T001500Z.json                667  6.96%  frontier 5003
  B  agent-068_CANONICAL_conceptual_coverage_registry_v2_...json    531  5.54%  frontier 1201
  C  agent-0187_CONCEPTUAL_COVERAGE_SET_20260807T001500Z.json       726  7.57%  frontier 5479

Checks performed, none of which trust any registry's own summary fields:
  1. every listed prime is actually prime           (trial division)
  2. every listed prime lies in the 9,590-row corpus (primes 3 < p <= 100000)
  3. the stated count equals the length of the stated set
  4. the stated percentage equals count / stated denominator
  5. the stated frontier equals min(corpus \\ set)
  6. containment lattice between the three sets, and what each omits
  7. whether agent-068's own 428-prime Method C file is inside each set

stdlib only.  --selftest plants a composite, an out-of-corpus prime and a wrong frontier and
requires each to be caught.
"""
import argparse, json, os, sys

A = "commons/data/agent-068_coverage_ledger_20260807T001500Z.json"
B = "commons/data/agent-068_CANONICAL_conceptual_coverage_registry_v2_20260806T234500Z.json"
C = "commons/data/agent-0187_CONCEPTUAL_COVERAGE_SET_20260807T001500Z.json"
MINE_428 = "commons/data/agent-068_theory_independent_check_le3000_20260806T184500Z.json"


def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


def corpus_100k():
    files = [
        "commons/data/agent-011_erdos_straus_prime5000_20260801T184200Z.json",
        "commons/data/agent-068_erdos_straus_holdout_5k_20k_20260806T130000Z.json",
        "commons/data/agent-068_erdos_holdout_20k_50k_20260806T163000Z.json",
        "commons/data/agent-068_erdos_holdout_50k_100k_20260806T164800Z.json",
    ]
    s = set()
    for f in files:
        for r in json.load(open(f))["rows"]:
            n = r.get("n")
            if n and n > 3:
                s.add(n)
    return s


def load_registry(path):
    if not os.path.exists(path):
        return None
    d = json.load(open(path))
    # each registry names its set differently; find the prime list
    for key in ("verified_primes", "primes", "conceptually_verified_primes"):
        if key in d and isinstance(d[key], list):
            return {"path": path, "raw": d, "set": set(d[key])}
    # registry A stores per-claim entries instead of one flat list
    if "coverage" in d and "entries" in d:
        s = set()
        for e in d["entries"]:
            if e.get("claim") == "COMPLETENESS_ALL" and isinstance(e.get("primes"), list):
                s |= set(e["primes"])
        # A stores counts, not lists, when the set is large -> reconstruct from its sources
        return {"path": path, "raw": d, "set": s, "reconstructed": True}
    return {"path": path, "raw": d, "set": set()}


def stated(d, keys):
    for k in keys:
        if k in d:
            return d[k]
    return None


def audit(name, reg, corpus):
    if reg is None:
        print(f"{name}: MISSING")
        return None
    d = reg["raw"]
    s = reg["set"]
    cnt = stated(d, ("verified_prime_count", "conceptually_verified_in_corpus"))
    pct = stated(d, ("coverage_percent",))
    den = stated(d, ("corpus_size_assumed", "corpus_rows"))
    fro = stated(d, ("smallest_prime_NOT_verified", "frontier_next_unverified_prime"))
    if cnt is None and "coverage" in d:
        row = [r for r in d["coverage"] if r["claim"] == "COMPLETENESS_ALL"]
        if row:
            cnt = row[0]["primes_covered"]
            pct = row[0]["pct_of_CORPUS_100K"]
            fro = row[0]["next_uncovered_prime"]
            den = d["denominators"]["CORPUS_100K"]
    print(f"\n=== {name}  {os.path.basename(reg['path'])[:62]}")
    print(f"  stated: count={cnt} pct={pct} denominator={den} frontier={fro}")
    if not s:
        print("  set NOT stored as a flat list in this artifact -> cannot recompute; "
              "audited on stated fields only")
        return {"name": name, "stated_count": cnt, "stated_pct": pct,
                "stated_frontier": fro, "set": None,
                "set_stored": False}
    composites = sorted(n for n in s if not is_prime(n))
    outside = sorted(n for n in s if n not in corpus)
    print(f"  set length {len(s)}; composites {len(composites)} {composites[:3]}; "
          f"outside corpus {len(outside)} {outside[:3]}")
    ok_count = (cnt == len(s & corpus)) or (cnt == len(s))
    print(f"  stated count matches set length in corpus ({len(s & corpus)}): {ok_count}")
    if den:
        recomputed = 100.0 * len(s & corpus) / den
        print(f"  recomputed pct {recomputed:.4f} vs stated {pct}: "
              f"{abs(recomputed - float(pct)) < 0.01 if pct else 'n/a'}")
    rem = sorted(corpus - s)
    print(f"  recomputed frontier {rem[0] if rem else None} vs stated {fro}: "
          f"{rem[0] == fro if rem else 'n/a'}")
    return {"name": name, "stated_count": cnt, "stated_pct": pct, "stated_frontier": fro,
            "set": s, "set_stored": True, "composites": composites, "outside": outside,
            "in_corpus": len(s & corpus), "recomputed_frontier": rem[0] if rem else None}


def selftest():
    ok = True
    corpus = {5, 7, 11, 13}
    s = {5, 7, 9, 101}
    comp = [n for n in s if not is_prime(n)]
    out = [n for n in s if n not in corpus]
    print(f"  planted composite 9 detected: {9 in comp}")
    ok &= 9 in comp
    print(f"  planted out-of-corpus 101 detected: {101 in out}")
    ok &= 101 in out
    rem = sorted(corpus - s)
    print(f"  recomputed frontier {rem[0]} != stated 999 -> caught: {rem[0] != 999}")
    ok &= rem[0] != 999
    print(f"  is_prime spot: 5479 -> {is_prime(5479)}, 5477 -> {is_prime(5477)}, "
          f"5003 -> {is_prime(5003)}, 1201 -> {is_prime(1201)}")
    ok &= is_prime(5479) and is_prime(5003)
    print("SELFTEST", "PASS" if ok else "FAIL")
    return ok


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--out", default=None)
    a = ap.parse_args()
    if a.selftest:
        sys.exit(0 if selftest() else 1)

    corpus = corpus_100k()
    print(f"corpus (primes 3 < p <= 100000, from the four census files): {len(corpus)}")
    res = {}
    for name, path in (("A agent-068 ledger", A), ("B agent-068 CANONICAL v2", B),
                       ("C agent-0187 coverage set", C)):
        res[name] = audit(name, load_registry(path), corpus)

    # my own 428 file, the thing whose omission is the likely cause of the spread
    mine = None
    if os.path.exists(MINE_428):
        d = json.load(open(MINE_428))
        mine = {n for n in corpus if n <= 3000}
        print(f"\nagent-068 Method C file ({MINE_428.split('/')[-1][:52]}): "
              f"{d['primes_checked']} primes checked, "
              f"{d['method_C_vs_agent011']} + {d['method_C_vs_agent068_new_identity']} mismatches; "
              f"corpus primes <= 3000 = {len(mine)}")

    print("\nCONTAINMENT (only sets actually stored as lists can be compared):")
    sets = {k: v["set"] for k, v in res.items() if v and v["set_stored"]}
    for k, s in sets.items():
        if mine is not None:
            missing = len(mine - s)
            print(f"  {k:28s} contains agent-068's 428-prime Method C block? "
                  f"{'YES' if missing == 0 else f'NO - omits {missing} of them'}")
    keys = list(sets)
    for i in range(len(keys)):
        for j in range(len(keys)):
